"],"release_date":"2016-07-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/mMtUybQ6hL24FXo0F3Z4j2KG7kZ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/vfJFJPepRKapMd5G2ro7klIRysq.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//mMtUybQ6hL24FXo0F3Z4j2KG7kZ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//vfJFJPepRKapMd5G2ro7klIRysq.jpg"},{"tmdb_id":157336,"title":"Interstellar","description":"The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.","duration":"2:49:00","genre":["Adventure","Drama","Science Fiction"],"release_date":"2014-11-04","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/8sNiAPPYU14PUepFNeSNGUTiHW.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//8sNiAPPYU14PUepFNeSNGUTiHW.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg"},{"tmdb_id":680,"title":"Pulp Fiction","description":"A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.","duration":"2:34:00","genre":["Thriller","Crime","Comedy"],"release_date":"1994-09-10","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//suaEOtk1N1sgg2MTM7oZd2cfVp3.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg"},{"tmdb_id":14537,"title":"Harakiri","description":"Down-on-his-luck veteran Tsugumo Hanshirō enters the courtyard of the prosperous House of Iyi. Unemployed, and with no family, he hopes to find a place to commit seppuku—and a worthy second to deliver the coup de grâce in his suicide ritual. The senior counselor for the Iyi clan questions the ronin’s resolve and integrity, suspecting Hanshirō of seeking charity rather than an honorable end. What follows is a pair of interlocking stories which lay bare the difference between honor and respect, and promises to examine the legendary foundations of the Samurai code.","duration":"2:15:00","genre":["Action","Drama","History"],"release_date":"1962-09-15","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/nC3IjYhUgZWgfKfFX0ygMigFwgc.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/5konZnIbcAxZjP616Cz5o9bKEfW.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//nC3IjYhUgZWgfKfFX0ygMigFwgc.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//5konZnIbcAxZjP616Cz5o9bKEfW.jpg"},{"tmdb_id":429,"title":"The Good, the Bad and the Ugly","description":"While the Civil War rages on between the Union and the Confederacy, three men – a quiet loner, a ruthless hitman, and a Mexican bandit – comb the American Southwest in search of a strongbox containing $200,000 in stolen gold.","duration":"2:41:00","genre":["Western"],"release_date":"1966-12-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/x4biAVdPVCghBlsVIzB6NmbghIz.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//x4biAVdPVCghBlsVIzB6NmbghIz.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg"},{"tmdb_id":13,"title":"Forrest Gump","description":"A man with a low IQ has accomplished great things in his life and been present during significant historic events—in each case, far exceeding what anyone imagined he could do. But despite all he has achieved, his one true love eludes him.","duration":"2:22:00","genre":["Comedy","Drama","Romance"],"release_date":"1994-06-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/saHP97rTPS5eLmrLQEcANmKrsFl.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//66Kn4XWhkuPkJxOJyPEx4U2CUfN.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//saHP97rTPS5eLmrLQEcANmKrsFl.jpg"},{"tmdb_id":667257,"title":"Impossible Things","description":"After the death of her abusive husband, Matilde finds her new best friend in Miguel, her young, insecure, and disoriented neighbor.","duration":"1:28:00","genre":["Family","Drama"],"release_date":"2021-06-17","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/bxSBOAD8AuMHYMdW3jso9npAkgt.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/t2Ew8NZ8Ci2kqmoecZUNQUFDJnQ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//bxSBOAD8AuMHYMdW3jso9npAkgt.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//t2Ew8NZ8Ci2kqmoecZUNQUFDJnQ.jpg"},{"tmdb_id":969681,"title":"Spider-Man: Brand New Day","description":"Fighting crime full-time as Spider-Man in a world that doesn''t remember him—and the pressure of seeing his old friends move on without him—sparks a change in Peter Parker he may not have the power to control. But that transformation might also be the only thing that can stop a shocking new threat to the city and those he loves - a powerful villain no one can even see.","duration":"2:25:00","genre":["Science Fiction","Action","Adventure"],"release_date":"2026-07-29","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/4tjxYg2AbOzzG9G1YuiT2NzYhlH.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//4tjxYg2AbOzzG9G1YuiT2NzYhlH.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg"},{"tmdb_id":12477,"title":"Grave of the