":"2015-06-04","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9h5BsxRmxLAvASADo2VcTlTUdb0.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/u1tDQun2iJAzersd94S8P47WEOL.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//9h5BsxRmxLAvASADo2VcTlTUdb0.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//u1tDQun2iJAzersd94S8P47WEOL.jpg"},{"tmdb_id":3175,"title":"Barry Lyndon","description":"An Irish rogue uses his cunning and wit to work his way up the social classes of 18th century England, transforming himself from the humble Redmond Barry into the noble Barry Lyndon.","duration":"3:08:00","genre":["Drama","History"],"release_date":"1975-12-16","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ef6SvWbSfCFlKodJZqpIaTvsRRP.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/A0byHUHMwZ7dtBQtfZ44QIgDbjo.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ef6SvWbSfCFlKodJZqpIaTvsRRP.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//A0byHUHMwZ7dtBQtfZ44QIgDbjo.jpg"},{"tmdb_id":521,"title":"Dial M for Murder","description":"When her American lover visits London, a wealthy woman’s jealous husband hatches a plan to murder her and inherit her fortune.","duration":"1:45:00","genre":["Thriller","Crime","Drama"],"release_date":"1954-05-29","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/mD6EAjfIr7CLdFlCIJjh7CJeWX3.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/2gDCAgl2iBQNuJuk6p2xtuS1ewg.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//mD6EAjfIr7CLdFlCIJjh7CJeWX3.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//2gDCAgl2iBQNuJuk6p2xtuS1ewg.jpg"},{"tmdb_id":204,"title":"The Wages of Fear","description":"In a run-down South American town, four men are paid to drive trucks loaded with nitroglycerin into the jungle through to the oil field. Friendships are tested and rivalries develop as they embark upon the perilous journey.","duration":"2: