B2M8UF8wc9flfGWkcgkTTf8Mzr.jpg"},{"tmdb_id":937746,"title":"Io Capitano","description":"Longing for a brighter future, two Senegalese teenagers embark on a journey from West Africa to Italy. However, between their dreams and reality lies a labyrinth of checkpoints, the Sahara Desert, and the vast waters of the Mediterranean.","duration":"2:01:00","genre":["Adventure","Drama"],"release_date":"2023-09-07","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/rniS6AOKTOr5PV7Xok6m7QSzlXg.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/kGlZFwUQI5gAUdySNFfqGIkAF9n.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//rniS6AOKTOr5PV7Xok6m7QSzlXg.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//kGlZFwUQI5gAUdySNFfqGIkAF9n.jpg"},{"tmdb_id":650031,"title":"The Shadow in My Eye","description":"On March 21st, 1945, the British Royal Air Force set out on a mission to bomb Gestapo''s headquarters in Copenhagen. The raid had fatal consequences as some of the bombers accidentally targeted a school and more than 120 people were killed, 86 of whom were children.","duration":"1:47:00","genre":["War","Drama","History"],"release_date":"2021-10-28","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6LtEzA3Umx9mc0lq1g8xOfluGPx.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/jCKvbH3a4V5IPoRAG85eDaniNqO.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//6LtEzA3Umx9mc0lq1g8xOfluGPx.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//jCKvbH3a4V5IPoRAG85eDaniNqO.jpg"},{"tmdb_id":14282,"title":"Ninja Scroll","description":"Jubei is a masterless ninja who travels the land alone, lending his services to those with gold—or a worthy cause. His fearsome abilities have served him well, but a plot to overthrow the government threatens to end his wandering ways—and possibly his life.","duration":"1:34:00","genre":["Fantasy","Animation","Action","Horror"],"release_date":"1993-06-05","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/mOd8oNCNyKOXs58FzdD1pPygWD.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/qzZEnaXwv4wss2QalEo4Uf9BAwh.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//mOd8oNCNyKOXs58FzdD1pPygWD.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//qzZEnaXwv4wss2QalEo4Uf9BAwh.jpg"},{"tmdb_id":585511,"title":"Luck","description":"Suddenly finding herself in the never-before-seen Land of Luck, the unluckiest person in the world must unite with the magical creatures there to turn her luck around.","duration":"1:45:00","genre":["Animation","Adventure","Comedy","Fantasy","Family"],"release_date":"2022-08-05","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/sKvQUSyqsFq8e1ts6oo3Xp3dPH2.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/1HOYvwGFioUFL58UVvDRG6beEDm.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//sKvQUSyqsFq8e1ts6oo3Xp3dPH2.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//1HOYvwGFioUFL58UVvDRG6beEDm.jpg"},{"tmdb_id":367412,"title":"Whiplash","description":"A ferocious, bullying music teacher teaches a dedicated student.","duration":"0:18:00","genre":["Drama","Music"],"release_date":"2013-01-18","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/sO70LyX3CHDNimbUwdGqL6pjrD3.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/dd0MyXqrgIi6s3CqFBMURXjUCEQ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//sO70LyX3CHDNimbUwdGqL6pjrD3.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//dd0MyXqrgIi6s3CqFBMURXjUCEQ.jpg"},{"tmdb_id":46591,"title":"Fists in the Pocket","description":"A deeply disturbed and epileptic young man benignly decides to murder other members of his dysfunctional family for altruistic reasons.","duration":"1:50:00","genre":["Drama"],"release_date":"1965-10-26","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/l6lpFI2qimWC0ra2s3WBQm9Zylx.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/xEMvB9iuUD8Ol4MeUZxVpoRHopl.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//l6lpFI2qimWC0ra2s3WBQm9Zylx.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//xEMvB9iuUD8Ol4MeUZxVpoRHopl.jpg"},{"tmdb_id":11602,"title":"Through a Glass Darkly","description":"Karin hopes to recover from her recent stay at a mental hospital by spending the summer at her family''s cottage on a tiny island. Her husband, Martin, cares for her but is frustrated by her physical withdrawal. Her younger brother, Minus, is confused by Karin''s vulnerability and his own budding sexuality. Their father, David, cannot overcome his haughty remoteness. Beset by visions, Karin descends further into madness.","duration":"1:31:00","genre":["Drama"],"release_date":"1961-10-16","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/xUvE2qim7mBzdUomoYDP9YC8gsZ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/rYD30Fm4vAcBqk1kTsxHw1s8P29.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//xUvE2qim7mBzdUomoYDP9YC8gsZ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//rYD30Fm4vAcBqk1kTsxHw1s8P29.jpg"},{"tmdb_id":5000,"title":"Forbidden Games","description":"Orphaned after a Nazi air raid, Paulette, a young Parisian girl, runs into Michel, an older peasant boy, and the two quickly become close. Together, they try to make sense of the chaotic and crumbling world around them, attempting to cope with death as they create a burial ground for Paulette''s deceased pet dog. Eventually, however, Paulette''s stay with Michel''s family is threatened by the harsh realities of wartime.","duration":"1:27:00","genre":["Drama","War"],"release_date":"1952-05-09","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/iNkgF4uBzcFTrY3NN6JrlCD5Ho.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/nby91GNVXQAv1NmKvqlpEEdhcMQ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//iNkgF4uBzcFTrY3NN6JrlCD5Ho.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//nby91GNVXQAv1NmKvqlpEEdhcMQ.jpg"},{"tmdb_id":760774,"title":"One Life","description":"British stockbroker Nicholas Winton visits Czechoslovakia in the 1930s and forms plans to assist in the rescue of Jewish children before the onset of World War II, in an operation that came to be known as the Kindertransport.","duration":"1:49:00","genre":["History","Drama"],"release_date":"2023-12-21","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7kgDHoXEk0EySTczcmaYpPDBFQS.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yvnIWt2j8VnDgwKJE2VMiFMa2Qo.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//7kgDHoXEk0EySTczcmaYpPDBFQS.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//yvnIWt2j8VnDgwKJE2VMiFMa2Qo.jpg"},{"tmdb_id":19884,"title":"The Sword of Doom","description":"Ryunosuke, a gifted swordsman plying his trade during the turbulent final days of Shogunate rule, has no moral code and kills without remorse. It’s a way of life that leads to madness.","duration":"2:02:00","genre":["Drama","Crime","Action"],"release_date":"1966-02-25","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/4qEw9OXqagoJDW0vpzLL5Fe1Mt0.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yjHbIihqpuAXlZVoPbWdqaukllB.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//4qEw9OXqagoJDW0vpzLL5Fe1Mt0.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//yjHbIihqpuAXlZVoPbWdqaukllB.jpg"},{"tmdb_id":1394,"title":"Nostalgia","description":"Russian poet Andrei Gorchakov journeys through Italy with his interpreter Eugenia to research the life of an 18th-century Russian composer who once lived abroad. Isolated and consumed by an unrelenting longing for his homeland, Andrei becomes drawn to Domenico, a radical mystic obsessed with spiritual redemption. Through austere imagery and extended temporal rhythms, Tarkovsky examines exile, memory, and the profound melancholy of being unable to belong fully to either place or language.","duration":"2:04:00","genre":["Drama","Romance"],"release_date":"1983-05-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/z0ZAEC2aZuflzua3HOSygVzE6Jq.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fCYSidPXp3LpDa9wlLNv0gZvjyF.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//z0ZAEC2aZuflzua3HOSygVzE6Jq.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//fCYSidPXp3LpDa9wlLNv0gZvjyF.jpg"},{"tmdb_id":1367642,"title":"Reminders of Him","description":"When Diem''s custodial grandparents adamantly refuse Kenna''s attempts to see her daughter, Kenna discovers unexpected compassion, and then something truer and deeper, with former NFL player and local bar owner Ledger. As their secret romance develops, so do the dangers for both of them, leading Kenna toward heartbreak and, ultimately, the hope for a second chance.","duration":"1:54:00","genre":["Romance","Drama"],"release_date":"2026-03-11","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/5rxEnsgriw8z065q51lrvPKYmCL.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7L6rceYgzQ0NeHD7PRDNrRoQ291.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//5rxEnsgriw8z065q51lrvPKYmCL.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//7L6rceYgzQ0NeHD7PRDNrRoQ291.jpg"},{"tmdb_id":508943,"title":"Luca","description":"Luca and his best friend Alberto experience an unforgettable summer on the Italian Riviera. But all the fun is threatened by a deeply-held secret: they are sea monsters from another world just below the water’s surface.","duration":"1:35:00","genre":["Animation","Family","Fantasy","Drama","Comedy"],"release_date":"2021-06-17","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/620hnMVLu6RSZW6a5rwO8gqpt0t.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9x4i9uKGXt8IiiIF5Ey0DIoY738.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//620hnMVLu6RSZW6a5rwO8gqpt0t.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//9x4i9uKGXt8IiiIF5Ey0DIoY738.jpg"},{"tmdb_id":29458,"title":"One Hundred Steps","description":"Peppino Impastato is a quick-witted lad growing up in 1970s Sicily. Despite hailing from a family with Mafia ties and living just one hundred steps from the house of local boss Tano Badalamenti, Peppino decides to expose the Mafia by using a pirate radio station to broadcast his political pronouncements in the form of ironic humour.","duration":"1:54:00","genre":["Drama","History"],"release_date":"2000-09-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lkdP7XOj3OnbeyVP79Rbxckkz5R.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/dpQpjLslfQlpDv7eCVRDPQAKgqs.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//lkdP7XOj3OnbeyVP79Rbxckkz5R.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//dpQpjLslfQlpDv7eCVRDPQAKgqs.jpg"},{"tmdb_id":18352,"title":"The Cremator","description":"In 1930s Prague, a Czech cremator who firmly believes cremation relieves one from earthly suffering is drawn inexorably to Nazism.","duration":"1:41:00","genre":["Horror","Drama","Crime","Comedy"],"release_date":"1969-03-14","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fMjdPM3pdc7T0NVoVqXtXEuJvG2.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9or2Jzw9HOE4gp9niwXBkZdpTVx.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//fMjdPM3pdc7T0NVoVqXtXEuJvG2.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//9or2Jzw9HOE4gp9niwXBkZdpTVx.jpg"},{"tmdb_id":925,"title":"Do the Right Thing","description":"Sal is the Italian owner of a pizzeria in Brooklyn. A neighborhood local, Buggin'' Out, becomes upset when he sees that the pizzeria''s Wall of Fame exhibits only Italian actors. Buggin'' Out believes a pizzeria in a black neighborhood should showcase black actors, but Sal disagrees. The wall becomes a symbol of racism and hate to Buggin'' Out and to other people in the neighborhood, and tensions rise.","duration":"2:00:00","genre":["Drama"],"release_date":"1989-06-14","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/xnLh9CNRxkpkSNikVhi5qLwcfUG.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/63rmSDPahrH7C1gEFYzRuIBAN9W.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//xnLh9CNRxkpkSNikVhi5qLwcfUG.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//63rmSDPahrH7C1gEFYzRuIBAN9W.jpg"},{"tmdb_id":277216,"title":"Straight Outta Compton","description":"In 1987, five young men, using brutally honest rhymes and hardcore beats, put their frustration and anger about life in the most dangerous place in America into the most powerful weapon they had: their music.  Taking us back to where it all began, Straight Outta Compton tells the true story of how these cultural rebels—armed only with their lyrics, swagger, bravado and raw talent—stood up to the authorities that meant to keep them down and formed the world’s most dangerous group, N.W.A.  And as they spoke the truth that no one had before and exposed life in the hood, their voice ignited a social revolution that is still reverberating today.","duration":"2:27:00","genre":["Drama","Music","History"],"release_date":"2015-08-11","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/8r9RoGfwGmn1pn0G3sbvHHemSWF.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/1CiLJx8Xtv3TbbFj6k7BboSmKgC.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//8r9RoGfwGmn1pn0G3sbvHHemSWF.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//1CiLJx8Xtv3TbbFj6k7BboSmKgC.jpg"},{"tmdb_id":212162,"title":"Puella Magi Madoka Magica the Movie -Rebellion-","description":"Following Madoka''s rewriting of the universe, sacrificing herself and her happy normal days to save all magical girls from the cruel fate that awaited them by wiping witches out of existence, the despair still manifest into creatures known as nightmares. Magical girl Homura Akemi continues to fight alone in the hope that she will be able to see Madoka smile again.","duration":"1:57:00","genre":["Mystery","Animation","Fantasy"],"release_date":"2013-10-26","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/tjWDJoTul5wn6BpnMH4ZWVcFWfx.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/68cts97TtCXcAlimoAHrHlQUNfn.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//tjWDJoTul5wn6BpnMH4ZWVcFWfx.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//68cts97TtCXcAlimoAHrHlQUNfn.jpg"},{"tmdb_id":14069,"title":"The Girl Who Leapt Through Time","description":"When 17-year-old Makoto Konno gains the ability to ''leap'' backwards through time, she immediately sets about improving her grades and preventing personal mishaps. However, she soon realises that changing the past isn''t as simple as it seems, and eventually, will have to rely on her new powers to shape the future of herself and her friends.","duration":"1:38:00","genre":["Fantasy","Animation","Drama","Science Fiction"],"release_date":"2006-07-15","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6m2qbAqSMJTX4HUwRvVEQI6ioiO.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fmK92C7HGu6sK0axItlQ0YsO9qR.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//6m2qbAqSMJTX4HUwRvVEQI6ioiO.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//fmK92C7HGu6sK0axItlQ0YsO9qR.jpg"},{"tmdb_id":1417,"title":"Pan''s Labyrinth","description":"In post–civil war Spain, 10-year-old Ofelia moves with her pregnant mother to live under the control of her cruel stepfather. Drawn into a mysterious labyrinth, she meets a faun who reveals that she may be a lost princess from an underground kingdom. To return to her true father, she must complete a series of surreal and perilous tasks that blur the line between reality and fantasy.","duration":"1:58:00","genre":["Fantasy","Drama","War"],"release_date":"2006-10-11","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6G6nqSW9S7EHA9HrYl0Z8uo2H7f.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7wb2Ldp0oAx1lcZvffq9RfWoI2h.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//6G6nqSW9S7EHA9HrYl0Z8uo2H7f.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//7wb2Ldp0oAx1lcZvffq9RfWoI2h.jpg"},{"tmdb_id":136,"title":"Freaks","description":"A circus'' beautiful trapeze artist agrees to marry the leader of side-show performers, but his deformed friends discover she is only marrying him for his inheritance.","duration":"1:04:00","genre":["Drama","Horror"],"release_date":"1932-01-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/r18vpGFsNf6n984x4KdJmAAWKkP.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fX2Wxd0W9E7eVClUd8kJTfennoV.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//r18vpGFsNf6n984x4KdJmAAWKkP.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//fX2Wxd0W9E7eVClUd8kJTfennoV.jpg"},{"tmdb_id":262,"title":"The King of Comedy","description":"Aspiring comic Rupert Pupkin attempts to achieve success in show business by stalking his idol, a late night talk-show host who craves his own privacy.","duration":"1:49:00","genre":["Drama","Comedy"],"release_date":"1982-12-18","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7Mh1DM4kCMbN93C2MlUavYbH5YM.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/m24EbHxT9NGYEkOlu29YcLOgjgK.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//7Mh1DM4kCMbN93C2MlUavYbH5YM.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//m24EbHxT9NGYEkOlu29YcLOgjgK.jpg"},{"tmdb_id":20871,"title":"Gentlemen of Fortune","description":"Kindergarten teacher Evgeniy Ivanovich Troshkin is reluctantly sent undercover to take the place of an imprisoned thief who stole Alexander the Great''s helmet. Evgeniy uses his striking resemblance to the thief to infiltrate his gang and learn the location of the stolen artifact. He finds the gangsters are unexpectedly similar to his students- they also need love and care.","duration":"1:28:00","genre":["Comedy","Crime","Drama"],"release_date":"1971-12-13","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ky6bvpEtk1cpmIDiV2hXsCXwiNs.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/owZ2KQ2x99XqMprSvFNeTdmCBk8.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ky6bvpEtk1cpmIDiV2hXsCXwiNs.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//owZ2KQ2x99XqMprSvFNeTdmCBk8.jpg"},{"tmdb_id":1675,"title":"Day for Night","description":"A committed filmmaker struggles to complete his latest project while coping with a myriad of crises, personal and professional, among the cast and crew.","duration":"1:56:00","genre":["Comedy","Drama"],"release_date":"1973-05-24","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/6MbFN88F27WvGC9WhAXq5KUIgTj.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/e5xDrSx6zDEUlMe2dWKGhv88PDZ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//6MbFN88F27WvGC9WhAXq5KUIgTj.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//e5xDrSx6zDEUlMe2dWKGhv88PDZ.jpg"},{"tmdb_id":1376434,"title":"Predator: Killer of Killers","description":"While three of the fiercest warriors in human history—a Viking raider, a ninja in feudal Japan, and a WWII pilot—are killers in their own right, they are merely prey for their new opponent: the ultimate killer of killers.","duration":"1:25:00","genre":["Animation","Action","Science Fiction","Thriller"],"release_date":"2025-06-05","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/3AGZKVr2DPT9H53gYtkSEC1tK1E.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/2XDQa6EmFHSA37j1t0w88vpWqj9.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//3AGZKVr2DPT9H53gYtkSEC1tK1E.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//2XDQa6EmFHSA37j1t0w88vpWqj9.jpg"},{"tmdb_id":901563,"title":"Close","description":"Two 13-year-old boys spend an idyllic summer together, but their connection is put to the test when they become the subject of speculation at school.","duration":"1:44:00","genre":["Drama"],"release_date":"2022-11-01","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/saESlYSTAGjr8gkyjoGb7omH0hf.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/dlMNnWs7Mz8Nk5AC447Ew1tD5pn.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//saESlYSTAGjr8gkyjoGb7omH0hf.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//dlMNnWs7Mz8Nk5AC447Ew1tD5pn.jpg"},{"tmdb_id":783675,"title":"The First Slam Dunk","description":"Shohoku''s “speedster” and point guard, Ryota Miyagi, always plays with brains and lightning speed, running circles around his opponents while feigning composure. In his second year of high school, Ryota plays with the Shohoku High School basketball team along with Sakuragi, Rukawa, Akagi, and Mitsui as they take the stage at the Inter-High School National Championship. And now, they are on the brink of challenging the reigning champions, Sannoh Kogyo High School.","duration":"2:05:00","genre":["Animation","Comedy","Drama"],"release_date":"2022-12-03","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/rBgzI1a126JWA7YJd7p1NBmC61z.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yq4tSiYvfGw150Ntq8NbsFZ12En.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//rBgzI1a126JWA7YJd7p1NBmC61z.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//yq4tSiYvfGw150Ntq8NbsFZ12En.jpg"},{"tmdb_id":269149,"title":"Zootopia","description":"Determined to prove herself, Officer Judy Hopps, the first bunny on Zootopia''s police force, jumps at the chance to crack her first case - even if it means partnering with scam-artist fox Nick Wilde to solve the mystery.","duration":"1:49:00","genre":["Animation","Adventure","Family","Comedy"],"release_date":"2016-02-11","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9tOkjBEiiGcaClgJFtwocStZvIT.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/hlK0e0wAQ3VLuJcsfIYPvb4JVud.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//9tOkjBEiiGcaClgJFtwocStZvIT.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//hlK0e0wAQ3VLuJcsfIYPvb4JVud.jpg"},{"tmdb_id":9421,"title":"The Dinner Game","description":"For Pierre Brochant and his friends, Wednesday is “Idiots'' Day”. The idea is simple: each person has to bring along an idiot. The one who brings the most spectacular idiot wins the prize. Tonight, Brochant is ecstatic. He has found a gem. The ultimate idiot, “A world champion idiot!”. What Brochant doesn’t know is that Pignon is a real jinx, a past master in the art of bringing on catastrophes...","duration":"1:20:00","genre":["Comedy"],"release_date":"1998-04-15","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/fxXwBvym6DkqkO4AWn8OjwMfMc1.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/cv6neov6SMLjHytjiU0rgeugoPI.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//fxXwBvym6DkqkO4AWn8OjwMfMc1.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//cv6neov6SMLjHytjiU0rgeugoPI.jpg"},{"tmdb_id":14756,"title":"Ip Man","description":"A semi-biographical account of Yip Man, the first martial arts master to teach the Chinese martial art of Wing Chun. The film focuses on events surrounding Ip that took place in the city of Foshan between the 1930s to 1940s during the Second Sino-Japanese War. Directed by Wilson Yip, the film stars Donnie Yen in the lead role, and features fight choreography by Sammo Hung.","duration":"1:46:00","genre":["Drama","Action","History"],"release_date":"2008-12-12","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/69QJSMkm5Hh0x9fLElZ8hjv5N4P.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/9bUIrDKnesNbBL1nAl1nt7gtocE.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//69QJSMkm5Hh0x9fLElZ8hjv5N4P.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//9bUIrDKnesNbBL1nAl1nt7gtocE.jpg"},{"tmdb_id":831223,"title":"Gone Mom: The Disappearance of Jennifer Dulos","description":"The story of Jennifer Dulos, the wealthy Connecticut mother-of-five who mysteriously vanished on May 24, 2019. Jennifer believed that she had found her Prince Charming in Fotis Dulos, but by the time of her disappearance, their 13-year marriage had disintegrated and they were engaged in a bitter divorce and a contentious custody dispute for their five children. When she disappeared without a trace after dropping off her children at school, the police turned the spotlight on Fotis, who claimed that Jennifer had staged her own disappearance a la Gone Girl.","duration":"1:28:00","genre":["Thriller","Mystery","Crime","TV Movie"],"release_date":"2021-06-05","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ip8BQ2qhW2QoGpuTLyEDrhhvf54.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/mzTNGnLG6LTHmrqrY0IADHDuyOJ.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ip8BQ2qhW2QoGpuTLyEDrhhvf54.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//mzTNGnLG6LTHmrqrY0IADHDuyOJ.jpg"},{"tmdb_id":12429,"title":"Ponyo","description":"When Sosuke, a young boy who lives on a clifftop overlooking the sea, rescues a stranded goldfish named Ponyo, he discovers more than he bargained for. Ponyo is a curious, energetic young creature who yearns to be human, but even as she causes chaos around the house, her father, a powerful sorcerer, schemes to return Ponyo to the sea.","duration":"1:40:00","genre":["Animation","Fantasy","Family"],"release_date":"2008-07-19","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/1QmEcK0w2Ub4Hm094fHbZT8vA7o.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/yp8vEZflGynlEylxEesbYasc06i.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//1QmEcK0w2Ub4Hm094fHbZT8vA7o.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//yp8vEZflGynlEylxEesbYasc06i.jpg"},{"tmdb_id":583,"title":"Life of Brian","description":"Brian Cohen is an average young Jewish man, but through a series of ridiculous events, he gains a reputation as the Messiah. When he''s not dodging his followers or being scolded by his shrill mother, the hapless Brian has to contend with the pompous Pontius Pilate and acronym-obsessed members of a separatist movement. Rife with Monty Python''s signature absurdity, the tale finds Brian''s life paralleling Biblical lore, albeit with many more laughs.","duration":"1:34:00","genre":["Comedy"],"release_date":"1979-08-17","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lOrM3OQhHlzEkpF7Ih3GghecrA8.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/lSSA64WF0M0BXnjwr2quMh6shCl.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//lOrM3OQhHlzEkpF7Ih3GghecrA8.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//lSSA64WF0M0BXnjwr2quMh6shCl.jpg"},{"tmdb_id":40662,"title":"Batman: Under the Red Hood","description":"One part vigilante, one part criminal kingpin, Red Hood begins cleaning up Gotham with the efficiency of Batman, but without following the same ethical code.","duration":"1:15:00","genre":["Mystery","Crime","Animation"],"release_date":"2010-07-27","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/jFEy7DClkMm8nGXAwmpe577Vlq0.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7lmHqHg1rG9b4U8MjuyQjmJ7Qm0.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//jFEy7DClkMm8nGXAwmpe577Vlq0.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//7lmHqHg1rG9b4U8MjuyQjmJ7Qm0.jpg"},{"tmdb_id":29452,"title":"The Face of Another","description":"A businessman with a disfigured face obtains a lifelike mask from his new doctor, but the mask starts altering his personality and causing him to question his identity.","duration":"2:02:00","genre":["Drama","Science Fiction"],"