NjM.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//cv7DeQQ7TOozPoTCBdNJIvWKhU1.jpg"},{"tmdb_id":632322,"title":"All My Life","description":"It was a chance meeting started by one of Sol’s friends trying to chat up Jennifer. However, in the end, it was those two who hit it off. Sol enjoyed Jen’s smile, her effort, and how silly she could be. Jen enjoyed Sol’s cooking, his athleticism, and that he would join her in fun moments. As you can imagine, love bloomed, and things got serious. Jen’s investment in Sol led to her pushing him to follow his dreams and even move in to save money. Sol’s investment in Jen well, it led to him proposing. But what started as a liver tumor grew into full-on cancer, so with a diagnosis of 6 months to live, Sol and Jennifer try to make the best of it.","duration":"1:33:00","genre":["Romance","Drama"],"release_date":"2020-10-23","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7Gzsn4yiwMSXvYcbWXsoDhq8QO2.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/xoKZ4ZkVApcTaTYlGoZ3J8xcIzG.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//7Gzsn4yiwMSXvYcbWXsoDhq8QO2.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//xoKZ4ZkVApcTaTYlGoZ3J8xcIzG.jpg"},{"tmdb_id":211954,"title":"Instructions Not Included","description":"Valentin is Acapulco''s resident playboy, until a former fling leaves a baby on his doorstep and him heading with her out of Mexico.","duration":"2:02:00","genre":["Comedy","Drama"],"release_date":"2013-08-30","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/eXcgXi3kTzkxLcHIvzaAaFj33NC.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/x3Ygv0aZbZ3iUMeXyIlSu0Ugyp5.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//eXcgXi3kTzkxLcHIvzaAaFj33NC.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//x3Ygv0aZbZ3iUMeXyIlSu0Ugyp5.jpg"},{"tmdb_id":21835,"title":"A Chinese Odyssey Part Two: Cinderella","description":"This sequel to \"Pandora''s Box\" continues director Jeffrey Lau''s adaptation of the Buddhism saga \"Journey to the West\". Stranded five centuries in the past, Joker Monkey King must battle a variety of monsters, seductive women and super-powered villains to save the dying Pak Jing-Jing.","duration":"1:39:00","genre":["Action","Adventure","Fantasy","Comedy","Romance","Drama"],"release_date":"1995-02-04","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/hbZT53Kng9UXWAq2oHaPPbp4B83.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ksloRonL1kOq4yErf9LOJ5qDhem.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//hbZT53Kng9UXWAq2oHaPPbp4B83.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//ksloRonL1kOq4yErf9LOJ5qDhem.jpg"},{"tmdb_id":1118224,"title":"Maharaja","description":"A barber seeks vengeance after his home is burglarized, cryptically telling police his \"Lakshmi\" has been taken, leaving them uncertain if it''s a person or object, jeer at his request until they learn what they''re really looking for.","duration":"2:21:00","genre":["Action","Thriller","Mystery"],"release_date":"2024-06-14","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/ot1UteJ1TL3xWuhkLRNzBULw4KJ.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/s0m4TM1XRAftQStgKpw024RvkJo.jpg","small_backdrop_path":"https://image.tmdb.org/t/p/w342//ot1UteJ1TL3xWuhkLRNzBULw4KJ.jpg","small_poster_path":"https://image.tmdb.org/t/p/w342//s0m4TM1XRAftQStgKpw024RvkJo.jpg"},{"tmdb_id":369299,"title":"Don''t Blame the Kid","description":"After a one-night stand results in pregnancy, a young woman decides to become partners with the emotionally immature father-to-be.","duration":"1:53:00","genre":["Comedy","Romance"],"release_date":"2016-05-13","backdrop_path":"https://image.tmdb.org/t/p/w600_and_h900_face/7NEySszUS4lvBn5MpnIJzGvhAy0.jpg","poster_path":"https://image.tmdb.org/t/p/w600_and_h900_face/zWp8QZ1KxNrirNK9MF1EAIHjqVw.jpg","small_backdrop_path":"https://image.tm